        """当前认证策略 (max_fail, lock_ms)，供配置导出/回滚点快照。"""
        return (self._max_fail, self._lock_ms)

    def set_policy(self, max_fail, lock_ms):
        """原子替换认证策略；用户凭据、失败计数与锁定记录全部保留。"""
        self._max_fail = max_fail
        self._lock_ms = lock_ms

